IZCodeAgentService.text:
export interface IZCodeAgentService {
  /**
   * 功能 #15 案内文档全文搜（RE-15；fork 扩展可选方法——上游 ZCode 无此方法，
   * 合成桥以 SQLite FTS5 实现，mock host 等其它实现方可不提供）。
   */
  searchSessionDocuments?(params: {
    workspacePath: string;
    workspaceIdentity?: string;
    sessionId: string;
    query: string;
    limit?: number;
  }): Promise<{
    mode: "fts" | "like" | "empty";
    results: Array<{ chunkId: string; kind: string; sourceLabel: string; text: string; createdAt: number }>;
  }>;
  /**
   * 功能 #25 文档对比（施工单-03 任务四；fork 扩展可选方法——上游 ZCode 无此方法，
   * 合成桥以 materials/ 目录为材料通道、确定性行 diff 产增/删/改清单，其它实现方可不提供）。
   */
  listWorkspaceDocuments?(params: {
    workspacePath: string;
  }): Promise<{
    dir: string;
    documents: Array<{ name: string; kind: "text" | "word"; size: number; updatedAt: number }>;
  }>;
  compareDocuments?(params: {
    workspacePath: string;
    leftName: string;
    rightName: string;
  }): Promise<{
    left: { name: string; text: string };
    right: { name: string; text: string };
    hunks: Array<{
      type: "add" | "del" | "mod";
      aStart: number; aCount: number;
      bStart: number; bCount: number;
      oldText: string; newText: string;
    }>;
    stats: { added: number; deleted: number; modified: number; unchangedOld: number; unchangedNew: number };
  }>;
  /**
   * 功能 #11 Word 红线改稿（施工单-03 任务一；fork 扩展可选方法——上游 ZCode 无此方法，
   * 合成桥以 oc28 会话通道出稿、SQLite 留存记录与决定，其它实现方可不提供）。
   */
  redlineRevise?(params: {
    workspacePath: string;
    materialName: string;
    instruction: string;
  }): Promise<{ revisionId: string; status: "revising" }>;
  redlineGet?(params: {
    workspacePath: string;
    revisionId: string;
  }): Promise<{
    revision: {
      revisionId: string;
      materialName: string;
      instruction: string;
      status: "revising" | "ready" | "failed" | "finalized";
      originalText: string;
      revisedText: string;
      finalText: string | null;
      finalPath: string | null;
      error: string | null;
      createdAt: number;
      updatedAt: number;
    };
    items: Array<{
      itemIdx: number;
      type: "add" | "del" | "mod";
      aStart: number; aCount: number;
      bStart: number; bCount: number;
      oldText: string; newText: string;
      decision: "pending" | "accepted" | "rejected";
    }>;
  }>;
  redlineList?(params: {
    workspacePath: string;
  }): Promise<{
    revisions: Array<{
      revisionId: string; materialName: string;
      status: "revising" | "ready" | "failed" | "finalized";
      itemCount: number; decidedCount: number; createdAt: number;
    }>;
  }>;
  redlineDecide?(params: {
    workspacePath: string;
    revisionId: string;
    itemIdx: number;
    decision: "accepted" | "rejected" | "pending";
  }): Promise<{
    revision: {
      revisionId: string;
      status: "revising" | "ready" | "failed" | "finalized";
      finalText: string | null;
      finalPath: string | null;
      error: string | null;
    };
    items: Array<{
      itemIdx: number;
      type: "add" | "del" | "mod";
      decision: "pending" | "accepted" | "rejected";
    }>;
  }>;
  redlineFinalize?(params: {
    workspacePath: string;
    revisionId: string;
  }): Promise<{ revisionId: string; status: "finalized"; finalPath: string }>;
  /**
   * 功能 #19 轻量知识图谱（步骤4·RE-19；fork 扩展可选方法——上游 ZCode 无此方法，
   * 合成桥以 graph 文档式 JSON 落桥同库 SQLite、写路径全量校验+版本乐观锁，其它实现方可不提供）。
   */
  caseGraphGet?(params: {
    workspacePath: string;
    workspaceIdentity?: string;
    caseId: string;
  }): Promise<
    | { exists: false; caseId: string }
    | { exists: true; caseId: string; revision: number; graph: unknown; updatedAt: number }
  >;
  caseGraphSave?(params: {
    workspacePath: string;
    workspaceIdentity?: string;
    caseId: string;
    baseRevision: number;
    graph: unknown;
  }): Promise<{ caseId: string; revision: number; updatedAt: string; nodeCount: number; edgeCount: number }>;
  caseGraphBuildPreview?(params: {
    workspacePath: string;
    workspaceIdentity?: string;
    caseId: string;
    caseName?: string;
  }): Promise<{
    caseId: string;
    available: boolean;
    partiesCount: number;
    materialsCount: number;
    note: string;
    proposal: { schemaVersion: number; title: string; nodes: unknown[]; edges: unknown[]; config: unknown; layout: unknown };
  }>;
  caseGraphClear?(params: {
    workspacePath: string;
    workspaceIdentity?: string;
    caseId: string;
    baseRevision: number;
  }): Promise<{ cleared: boolean; caseId: string }>;
  caseGraphReadSource?(params: {
    workspacePath: string;
    filename: string;
  }): Promise<{ name: string; text: string; truncated: boolean }>;

  /**
   * 功能 #29 新手引导与产品指引（RE-29；fork 扩展可选方法——上游 ZCode 无此方法，
   * 合成桥以 SQLite app_meta 三键+演示台账实现，其它实现方可不提供）。
   * 四元组：status(pending|completed)/demoChoice(blank|demo|null)/demoImported(台账查证)/
   * guideStatus(pending|completed|skipped，非法值归一 pending)。
   */
  onboardingGet?(): Promise<{
    status: "pending" | "completed";
    demoChoice: "blank" | "demo" | null;
    demoImported: boolean;
    guideStatus: "pending" | "completed" | "skipped";
  }>;
  onboardingComplete?(params: { demo?: boolean; startGuide?: boolean }): Promise<{
    status: "pending" | "completed";
    demoChoice: "blank" | "demo" | null;
    demoImported: boolean;
    guideStatus: "pending" | "completed" | "skipped";
  }>;
  onboardingGuideStatus?(params: { status: "pending" | "completed" | "skipped" }): Promise<{
    status: "pending" | "completed";
    demoChoice: "blank" | "demo" | null;
    demoImported: boolean;
    guideStatus: "pending" | "completed" | "skipped";
  }>;
  /**
   * 功能 #30 安全审计中心（步骤4·RE-30；fork 扩展可选方法——上游 ZCode 无此方法，
   * 合成桥以 audit_log 哈希链实现（一次往返同返 rows+chainOk），其它实现方可不提供）。
   */
  auditList?(params?: { limit?: number }): Promise<{
    rows: Array<{
      id: string;
      ts: string | null;
      actor: string | null;
      action: string;
      target: string | null;
      detail: string | null;
      prev_hash: string | null;
      hash: string;
    }>;
    chainOk: boolean;
  }>;
  /** 渲染层追加通道（RE-30 §3.4 等量保留任意写入面；本版渲染层无调用点，通道在即契约在）。 */
  auditAppend?(entry: Record<string, unknown>): Promise<true>;
  /**
   * 功能 #31 支持通道（RE-31 §3；fork 扩展可选方法——上游 ZCode 无此方法）。
   * supportInfoGet：上传目标解析（env JUSCITE_SUPPORT_OPS_API > ops-config.json > 无=null 降级）。
   * 工单/诊断线 fetch 无显式超时无重试（A8 等量）；60s 兜底在渲染层（A18 不向桥传取消）。
   */
  supportInfoGet?(): Promise<{
    opsApi: string | null;
    source: "env" | "file" | "none";
    supportDir: string;
    appVersion: string;
  }>;
  /**
   * 提交工单：有 opsApi=POST /support/tickets（body {requester, subject(trim 后), content|""，ticket_key}，
   * A6 等量）；无配置=降级落盘 %APPDATA%\Juscite\support\ticket-<UTC时间戳>.md（§3.5 Markdown，
   * E31/E32/E33）。responseTicketKey=服务端回显的 ticket_key（无回显=null，渲染层按加固 1 处理）。
   */
  supportTicketCreate?(params: {
    requester: string; subject: string; content?: string; ticketKey?: string;
  }): Promise<{
    mode: "remote" | "local"; ok: true; ticketKey: string;
    responseTicketKey?: string | null;
    path?: string; fileName?: string; content?: string; createdAt?: string;
  }>;
  /**
   * 工单列表：有 opsApi=GET /support/tickets?requester=<enc> + x-ticket-key 头（A10 等量，rows 原样
